<?php
namespace App\Controllers;
use App\Core\Auth; use App\Core\Csrf; use App\Core\Database; use App\Core\View;
final class AdminCommentsController {
 private function guard(): array { Auth::requireRole(['admin','editor']); return Auth::user(); }
 public function index(): void { $this->guard(); $status=(string)($_GET['status']??'pending'); if(!in_array($status,['pending','approved','spam','trash','all'],true))$status='pending'; $where=$status==='all'?'':'WHERE c.status=?'; $args=$status==='all'?[]:[$status]; $comments=Database::all("SELECT c.*,COALESCE(u.name,c.guest_name) author_name,COALESCE(u.email,c.guest_email) author_email,t.title article_title,t.slug article_slug,t.locale FROM article_comments c LEFT JOIN users u ON u.id=c.user_id LEFT JOIN article_translations t ON t.article_id=c.article_id AND t.locale=? ".str_replace('WHERE','AND',$where)." ORDER BY c.id DESC LIMIT 300",array_merge([default_locale()],$args)); $counts=[]; foreach(['pending','approved','spam','trash'] as $x)$counts[$x]=(int)(Database::one('SELECT COUNT(*) c FROM article_comments WHERE status=?',[$x])['c']??0); View::render('admin/comments',compact('comments','counts','status')+['title'=>'تعليقات المقالات'],'dashboard'); }
 public function action(): void { $this->guard(); Csrf::enforce(); $id=(int)($_POST['id']??0); $action=(string)($_POST['action']??''); $map=['approve'=>'approved','pending'=>'pending','spam'=>'spam','trash'=>'trash']; if($id>0 && isset($map[$action])){Database::exec('UPDATE article_comments SET status=? WHERE id=?',[$map[$action],$id]); audit_log('article_comment_'.$action,'article_comment',$id,'');} redirect('/admin/comments?status='.(isset($map[$action])?$map[$action]:'pending')); }
 public function delete(): void { $this->guard(); Csrf::enforce(); $id=(int)($_POST['id']??0); if($id>0){Database::exec('DELETE FROM article_comments WHERE id=?',[$id]); audit_log('article_comment_delete','article_comment',$id,'');} redirect('/admin/comments?status=trash'); }
 public function settings(): void { Auth::requireRole(['admin']); Csrf::enforce(); foreach(['comments_enabled','comments_require_moderation','comments_registered_autoapprove','comments_allow_guests','comments_allow_replies'] as $k) Database::exec("INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)",[$k,isset($_POST[$k])?'1':'0']); foreach(['comments_max_links','comments_rate_seconds','comments_blocked_words'] as $k){$v=trim((string)($_POST[$k]??'')); Database::exec("INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)",[$k,$v]);} flash('success','تم حفظ إعدادات التعليقات.'); redirect('/admin/comments#comment-settings'); }
}
